			Limit:             aws.Int64(fieldsMapPageSize),
			FilterExpression:  aws.String("attribute_exists(#fields)"),
			ExpressionAttributeNames: map[string]*string{
				"#fields": aws.String("Fields"),
			},
		})
		if err != nil {
			return trace.Wrap(convertError(err))
		}
		if out == nil {
			return trace.BadParameter("DynamoDB scan returned no result during FieldsMap migration")
		}

		requests := make([]*dynamodb.WriteRequest, 0, len(out.Items))
		for _, item := range out.Items {
			request, err := fieldsMapMigrationRequest(item)
			if err != nil {
				state.InvalidCount++
				log.WithFields(log.Fields{
					"table":       l.Tablename,
					"session_id":  aws.StringValue(item[keySessionID].S),
					"event_index": aws.StringValue(item[keyEventIndex].N),
				}).WithError(err).Error("Unable to convert DynamoDB audit event Fields")
				continue
			}
			requests = append(requests, request)
		}

		if err := writeFieldsMapBatches(ctx, client, l.Tablename, requests); err != nil {
			return trace.Wrap(err)
		}
		state.MigratedCount += int64(len(requests))
		state.LastEvaluatedKey = out.LastEvaluatedKey
		if err := l.saveFieldsMapMigrationState(ctx, state); err != nil {
			return trace.Wrap(err)
		}
		if len(requests) != 0 {
			log.WithFields(log.Fields{"table": l.Tablename, "migrated": state.MigratedCount, "invalid": state.InvalidCount}).Info("DynamoDB FieldsMap migration progress")
		}
		if len(out.LastEvaluatedKey) == 0 {
			break
		}
	}

	if state.InvalidCount != 0 {
		// Restart at the beginning on the next retry so invalid records are
		// revisited after they have been repaired. Valid records already written
		// as FieldsMap are excluded by the scan filter.
		if err := l.saveFieldsMapMigrationState(ctx, fieldsMapMigrationState{}); err != nil {
			return trace.Wrap(err)
		}
		return trace.BadParameter("FieldsMap migration could not convert %d audit events in table %q", state.InvalidCount, l.Tablename)
	}
	state.CompletedAt = l.backend.Clock().Now().UTC()
	if err := l.saveFieldsMapMigrationState(ctx, state); err != nil {
		return trace.Wrap(err)
	}
	log.WithFields(log.Fields{"table": l.Tablename, "migrated": state.MigratedCount}).Info("Completed DynamoDB FieldsMap migration pass")
	return nil
}

func fieldsMapMigrationRequest(item map[string]*dynamodb.AttributeValue) (*dynamodb.WriteRequest, error) {
	legacy := item["Fields"]
	if legacy == nil || legacy.S == nil {
		return nil, trace.BadParameter("legacy Fields attribute is not a string")
	}
	fieldsMap, err := fieldsMapFromJSON([]byte(*legacy.S))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	roundTrip, err := fieldsMapToJSON(fieldsMap)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err := validateFieldsMapContent([]byte(*legacy.S), roundTrip); err != nil {
		return nil, trace.Wrap(err)
	}
	if existing := item["FieldsMap"]; existing != nil {
		if existing.M == nil {
			return nil, trace.BadParameter("existing FieldsMap attribute is not a map")
		}
		existingJSON, err := fieldsMapToJSON(existing.M)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if err := validateFieldsMapContent([]byte(*legacy.S), existingJSON); err != nil {
			return nil, trace.WrapWithMessage(err, "existing FieldsMap differs from Fields")
		}
	}
	// Copy the item so a failed batch does not mutate a scan result reused by
	// callers or tests. Preserve every top-level attribute except legacy Fields.
	next := make(map[string]*dynamodb.AttributeValue, len(item))
	for key, value := range item {
		if key != "Fields" {
			next[key] = value
		}
	}
	next["FieldsMap"] = &dynamodb.AttributeValue{M: fieldsMap}
	return &dynamodb.WriteRequest{PutRequest: &dynamodb.PutRequest{Item: next}}, nil
}

func validateFieldsMapContent(legacyJSON, mapJSON []byte) error {
	decode := func(data []byte) (interface{}, error) {
		decoder := json.NewDecoder(bytes.NewReader(data))
		decoder.UseNumber()
		var value interface{}
		if err := decoder.Decode(&value); err != nil {
			return nil, trace.Wrap(err)
		}
		var extra interface{}
		if err := decoder.Decode(&extra); err != io.EOF {
			if err == nil {
				return nil, trace.BadParameter("multiple JSON values in event Fields")
			}
			return nil, trace.Wrap(err)
		}
		return value, nil
	}
	before, err := decode(legacyJSON)
	if err != nil {
		return trace.Wrap(err)
	}
	after, err := decode(mapJSON)
	if err != nil {
		return trace.Wrap(err)
	}
	if !reflect.DeepEqual(before, after) {
		return trace.BadParameter("FieldsMap changes event metadata")
	}
	return nil
}

func writeFieldsMapBatches(ctx context.Context, client fieldsMapMigrationClient, table string, requests []*dynamodb.WriteRequest) error {
	if len(requests) == 0 {
		return nil
	}
	jobs := make(chan []*dynamodb.WriteRequest, (len(requests)+DynamoBatchSize-1)/DynamoBatchSize)
	for len(requests) != 0 {
		count := DynamoBatchSize
		if len(requests) < count {
			count = len(requests)
		}
		jobs <- requests[:count]
		requests = requests[count:]
	}
	close(jobs)

	workerCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	var workers sync.WaitGroup
	var firstErr error
	var errOnce sync.Once
	workerCount := len(jobs)
	if workerCount > maxMigrationWorkers {
		workerCount = maxMigrationWorkers
	}
	for i := 0; i < workerCount; i++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for {
				select {
				case <-workerCtx.Done():
					return
				case batch, ok := <-jobs:
					if !ok {
						return
					}
					if err := writeFieldsMapBatch(workerCtx, client, table, batch); err != nil {
						errOnce.Do(func() { firstErr = err; cancel() })
						return
					}
				}
			}
		}()
	}
	workers.Wait()
	if firstErr != nil {
		return trace.Wrap(firstErr)
	}
	return trace.Wrap(ctx.Err())
}

func writeFieldsMapBatch(ctx context.Context, client fieldsMapMigrationClient, table string, requests []*dynamodb.WriteRequest) error {
	backoff := 50 * time.Millisecond
	for len(requests) != 0 {
		out, err := client.BatchWriteItemWithContext(ctx, &dynamodb.BatchWriteItemInput{
			RequestItems: map[string][]*dynamodb.WriteRequest{table: requests},
		})
		if err != nil {
			return trace.Wrap(convertError(err))
		}
		if out == nil {
			return trace.BadParameter("DynamoDB batch write returned no result during FieldsMap migration")
		}
		requests = out.UnprocessedItems[table]
		if len(requests) == 0 {
			return nil
		}
		select {
		case <-time.After(backoff):
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		}
		if backoff < 5*time.Second {
			backoff *= 2
		}
	}
	return nil
}
